import { Component } from 'preact'
import i18n from '../../i18n'
import { auth } from '../helpers'
import ResponseForm from './ResponseForm'

const CLASS = 'mv-responses'
const REVIEWS_CLASS = 'mv-comments'

class ReviewResponses extends Component {
  constructor(props) {
    super(props)

    this.state = {
      responses: [],
      loading: false,
      showForm: false,
      submitting: false
    }

    this.handleToggleForm = this.handleToggleForm.bind(this)
    this.handleSubmitResponse = this.handleSubmitResponse.bind(this)
    this.loadResponses = this.loadResponses.bind(this)
  }

  async componentDidMount() {
    await this.loadResponses()
  }

  async loadResponses() {
    const { reviewId } = this.props

    this.setState({ loading: true })

    try {
      const { data } = await auth.get(`mv-create/v1/reviews/${reviewId}/responses`)
      this.setState({ responses: data || [], loading: false })
    } catch (error) {
      console.error('Error loading responses:', error)
      this.setState({ loading: false })
    }
  }

  handleToggleForm() {
    this.setState(state => ({ showForm: !state.showForm }))
  }

  async handleSubmitResponse(responseData) {
    const { reviewId } = this.props

    this.setState({ submitting: true })

    try {
      const { data } = await auth.post(`mv-create/v1/reviews/${reviewId}/responses`, responseData)
      
      // Add new response to the list
      this.setState(state => ({
        responses: [...state.responses, data],
        submitting: false,
        showForm: false
      }))
    } catch (error) {
      console.error('Error submitting response:', error)
      this.setState({ submitting: false })
    }
  }

  render() {
    const { responses, loading, showForm, submitting } = this.state

    return (
      <div class={`${CLASS}`}>
        {loading && (
          <div class={`${CLASS}-loading`}>{i18n('LOADING')}</div>
        )}

        {responses.length > 0 && (
          <div class={`${CLASS}-list`}>
            <h4 class={`${CLASS}-title`}>{i18n('RESPONSES')}</h4>
            {responses.map(response => (
              <div key={response.id} class={`${CLASS}-item ${response.is_admin_response === '1' ? 'is-admin' : ''}`}>
                <div class={`${CLASS}-item-header`}>
                  <span class={`${REVIEWS_CLASS}-review-author`}>
                    {response.author_name}
                    {response.is_admin_response === '1' && (
                      <span class={`${CLASS}-admin-badge`}>{i18n('ADMIN')}</span>
                    )}
                  </span>
                  <span class={`${REVIEWS_CLASS}-review-date`}>
                    <time>{new Date(response.created * 1000).toLocaleString()}</time>
                  </span>
                </div>
                <div class={`${CLASS}-item-content`}>
                  <div dangerouslySetInnerHTML={{ __html: response.content }} />
                </div>
              </div>
            ))}
          </div>
        )}

        {window.MV_CREATE_SETTINGS?.__OPTIONS__?.canReplyToReviews && (
          <div class={`${CLASS}-form-toggle`}>
            <button onClick={this.handleToggleForm} class={`btn btn-primary ${CLASS}-toggle-btn`}>
              {showForm ? i18n('CANCEL_RESPONSE') : i18n('REPLY')}
            </button>
          </div>
        )}

        {showForm && (
          <ResponseForm
            onSubmit={this.handleSubmitResponse}
            onCancel={this.handleToggleForm}
            submitting={submitting}
          />
        )}
      </div>
    )
  }
}

export default ReviewResponses