import { useState } from 'preact/compat'
import './Stars.scss'

const STAR_PATH = 'M6,0,7.875,3.75,12,4.35,9,7.275,9.675,11.4,6,9.45,2.325,11.4,3,7.275,0,4.35l4.125-.6Z'

// Each star is 12 units wide with a 2-unit gap (slot=14). ViewBox width = 5*14 - 2 = 68.
const STAR_W = 12
const SLOT = 14
const VIEWBOX_W = 68

// Compute clip-path inset percentage to reveal exactly `rating` stars.
// Using preserveAspectRatio="none" so clip% maps 1:1 to SVG units.
const getClipRight = (rating) => {
  if (rating <= 0) return 100
  if (rating >= 5) return 0
  const whole = Math.floor(rating)
  const endX = whole * SLOT + (rating - whole) * STAR_W
  return ((1 - endX / VIEWBOX_W) * 100).toFixed(3)
}

const parseRating = (r) => {
  if (!r || r === 'na') return null
  const n = parseFloat(r)
  return isNaN(n) ? null : n
}

const getStarFromEvent = (e) => {
  const rect = e.currentTarget.getBoundingClientRect()
  const x = e.clientX - rect.left
  return Math.max(1, Math.min(5, Math.ceil((x / rect.width) * 5)))
}

const Stars = ({
  className,
  rating,
  globalRating,
  onClick,
  clickable = onClick,
}) => {
  const [hoverRating, setHoverRating] = useState(null)

  const userRating = parseRating(rating)
  const avgRating = parseRating(globalRating)
  const displayRating = hoverRating ?? userRating ?? avgRating ?? 0

  const isHoverColor = hoverRating !== null || userRating !== null
  const fillColor = isHoverColor
    ? 'var(--mv-star-fill-hover,var(--mv-star-fill,#c8a951))'
    : 'var(--mv-star-fill,#c8a951)'

  const clipRight = getClipRight(displayRating) + '%'
  const paths = [0, 1, 2, 3, 4].map(i => (
    <path key={i} d={STAR_PATH} transform={`translate(${i * 14})`} />
  ))

  return (
    <div
      class={`mv-reviews-stars mv-stars mv-star-ratings ${className}`}
      aria-label={`${displayRating} out of 5 stars`}
      onClick={clickable ? (e) => onClick(getStarFromEvent(e)) : undefined}
      onMouseMove={clickable ? (e) => setHoverRating(getStarFromEvent(e)) : undefined}
      onMouseLeave={clickable ? () => setHoverRating(null) : undefined}
      style={clickable ? 'cursor:pointer' : undefined}
    >
      <svg aria-hidden="true" viewBox="0 0 68 11.4" preserveAspectRatio="none" style="fill:var(--mv-star-empty,#ccc)">
        {paths}
      </svg>
      <svg
        aria-hidden="true"
        viewBox="0 0 68 11.4"
        preserveAspectRatio="none"
        style={`position:absolute;top:0;left:0;width:100%;clip-path:inset(0 ${clipRight} 0 0);fill:${fillColor}`}
      >
        {paths}
      </svg>
    </div>
  )
}

Stars.defaultProps = {
  className: '',
  rating: 'na',
  globalRating: 'na',
  onClick: () => null,
}

export default Stars
